<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { Link, router } from '@inertiajs/vue3';
import { Plus, Check, ListTodo, FolderKanban, Target, ChevronLeft, ChevronRight, Pencil, Trash2, LayoutGrid, List, GripVertical, CalendarDays, FileText, Search, Star } from 'lucide-vue-next';
import CalendarView from './CalendarView.vue';
import LifeModules from './LifeModules.vue';
import OrganizeView from './OrganizeView.vue';
import { request } from '../lib/api';

const props=defineProps<{section:string;selectedId?:string|null;user:any;settings:any;today:string;data:any;summary:any;lookups:any;pagination?:any}>();
const emit=defineEmits<{edit:[entity:string,record?:any,defaults?:any]}>();
const error=ref('');const loading=ref(false);const busy=ref<string[]>([]);const rows=ref<any[]>([]);
const page=ref(1);const lastPage=ref(1);const total=ref(0);const filter=ref('today');const projectFilter=ref('');const priority=ref('');const statusFilter=ref('');const goalFilter=ref('');const sort=ref('focus');const query=ref('');const projectView=ref('board');const showCompleted=ref(true);
const dragged=ref('');const hoverColumn=ref('');const stages=['backlog','todo','in_progress','done'];let loadSequence=0;let queryTimer:ReturnType<typeof setTimeout>;
const entity=computed(()=>props.section==='today'||(props.section==='projects'&&props.selectedId)?'tasks':'projects');
const project=computed(()=>(props.data.projects||[]).find((p:any)=>p.id===props.selectedId));
const goal=computed(()=>(props.lookups.goals||[]).find((g:any)=>g.id===project.value?.goal_id));
const openTasks=computed(()=>rows.value.filter(t=>t.status!=='done'));
const completedTasks=computed(()=>rows.value.filter(t=>t.status==='done'));
const labels:Record<string,string>={backlog:'Backlog',todo:'To Do',in_progress:'In Progress',done:'Done'};
function label(value:string){return value?.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());}
function date(value:string){if(!value)return '';const key=value.slice(0,10);const [y,m,d]=key.split('-');switch(props.settings.date_format){case 'Y-m-d':return key;case 'm/d/Y':return `${m}/${d}/${y}`;case 'd/m/Y':return `${d}/${m}/${y}`;default:return new Date(key+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});}}
function taskProject(task:any){return props.lookups.projects?.find((p:any)=>p.id===task.project_id)?.name;}
function readProps(){if(!['today','projects'].includes(props.section))return;rows.value=(props.data[entity.value]||[]).map((r:any)=>({...r}));const meta=props.pagination?.[entity.value]||{};page.value=1;lastPage.value=meta.last_page||1;total.value=meta.total??rows.value.length;}
watch(()=>props.data,()=>{readProps();if(query.value||priority.value||projectFilter.value||statusFilter.value||goalFilter.value||filter.value!=='today'||sort.value!=='focus')load();},{immediate:true});
function params(next:number){const p=new URLSearchParams({page:String(next),per_page:'50'});if(query.value)p.set('q',query.value);if(props.section==='today'){p.set('filter',filter.value);if(projectFilter.value)p.set('project_id',projectFilter.value);if(priority.value)p.set('priority',priority.value);}else if(props.selectedId)p.set('project_id',props.selectedId);else{p.set('sort',sort.value);if(statusFilter.value)p.set('status',statusFilter.value);if(goalFilter.value)p.set('goal_id',goalFilter.value);}return p;}
async function load(next=1){if(!['today','projects'].includes(props.section))return;const seq=++loadSequence;loading.value=true;error.value='';try{const response=await request(`/data/${entity.value}?${params(next)}`,'GET');if(seq!==loadSequence)return;rows.value=response.data;page.value=response.current_page;lastPage.value=response.last_page;total.value=response.total;}catch(e:any){if(seq===loadSequence)error.value=e.message;}finally{if(seq===loadSequence)loading.value=false;}}
watch([filter,projectFilter,priority,statusFilter,goalFilter,sort],()=>load());
watch(query,()=>{clearTimeout(queryTimer);queryTimer=setTimeout(()=>load(),250);});
onBeforeUnmount(()=>clearTimeout(queryTimer));
async function action(url:string,id:string,method='POST',payload:any={},redirectTo?:string){if(busy.value.includes(id))return;busy.value.push(id);error.value='';try{await request(url,method,payload);if(redirectTo)router.visit(redirectTo);else router.reload();}catch(e:any){error.value=Object.values(e.errors||{}).flat().join(' ')||e.message;}finally{busy.value=busy.value.filter(x=>x!==id);}}
function remove(kind:string,row:any){const warning=kind==='projects'?'The project will be removed from your active list. Its tasks and history will remain.':'This item will be removed from your active list.';if(window.confirm(`Delete “${row.name||row.title}”? ${warning}`))action(`/data/${kind}/${row.id}`,row.id,'DELETE',{},kind==='projects'&&row.id===props.selectedId?'/projects':undefined);}
function stageTasks(status:string){return rows.value.filter(t=>t.status===status).sort((a,b)=>a.sort_order-b.sort_order||a.id.localeCompare(b.id));}
async function moveTask(id:string,status:string,beforeId?:string){
 if(busy.value.includes('move'))return;busy.value.push('move');error.value='';const snapshot=rows.value.map(t=>({...t}));const moving=rows.value.find(t=>t.id===id);if(!moving){busy.value=[];return;}
 try{
  // Fetch the target column to retain manual ordering even beyond the current page.
  let target:any[]=[];let current=1;let final=1;do{const p=new URLSearchParams({project_id:props.selectedId||'',status,per_page:'100',page:String(current)});const r=await request(`/data/tasks?${p}`,'GET');target.push(...r.data);final=r.last_page;current++;}while(current<=final);
  target=target.filter(t=>t.id!==id).sort((a,b)=>a.sort_order-b.sort_order||a.id.localeCompare(b.id));let position=beforeId?target.findIndex(t=>t.id===beforeId):target.length;if(position<0)position=target.length;
  moving.status=status;moving.sort_order=position;dragged.value='';hoverColumn.value='';
  await request(`/data/tasks/${id}/move`,'POST',{status,sort_order:position});router.reload();
 }catch(e:any){rows.value=snapshot;error.value=e.message;}finally{busy.value=busy.value.filter(x=>x!=='move');}
}
function startDrag(event:DragEvent,task:any){dragged.value=task.id;event.dataTransfer?.setData('text/plain',task.id);if(event.dataTransfer)event.dataTransfer.effectAllowed='move';}
function drop(event:DragEvent,status:string,beforeId?:string){const id=dragged.value||event.dataTransfer?.getData('text/plain');if(id&&id!==beforeId)moveTask(id,status,beforeId);}
</script>

<template>
 <CalendarView v-if="section==='calendar'" :today="today" :settings="settings" :data="data" @edit="(entity,record,defaults)=>emit('edit',entity,record,defaults)"/>
 <LifeModules v-else-if="['finance','content','reviews','settings','assistant'].includes(section)" v-bind="props" @edit="(entity,record,defaults)=>emit('edit',entity,record,defaults)"/>
 <OrganizeView v-else-if="['goals','ideas','notes','habits'].includes(section)" v-bind="props" @edit="(entity,record,defaults)=>emit('edit',entity,record,defaults)"/>
 <section v-else class="execution-module">
  <p v-if="error" class="error-banner" role="alert">{{error}}</p>
  <template v-if="section==='today'">
   <header class="module-header"><div><div class="eyebrow">ONE THING AT A TIME</div><h1>Today</h1><p>{{new Date(today+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'})}} · {{summary.today?.completed_count||0}} of {{summary.today?.total_count||0}} tasks complete</p></div><button class="btn btn-primary" @click="emit('edit','tasks',undefined,{planned_date:today})"><Plus :size="17"/> Add task</button></header>
   <div class="task-view-progress"><div class="progress-track"><span :style="{width:(summary.today?.percentage||0)+'%'}"></span></div><span>{{summary.today?.percentage||0}}%</span></div>
   <div class="module-toolbar"><div class="tabs"><button v-for="tab in [{key:'today',label:'Today'},{key:'open',label:'All open'},{key:'overdue',label:'Overdue'},{key:'completed',label:'Completed'}]" :key="tab.key" class="tab" :class="{active:filter===tab.key}" @click="filter=tab.key">{{tab.label}}</button></div><div class="filters"><select v-model="projectFilter" aria-label="Filter tasks by project"><option value="">All projects</option><option v-for="p in lookups.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="priority" aria-label="Filter tasks by priority"><option value="">All priorities</option><option v-for="p in ['low','normal','high','urgent']" :key="p" :value="p">{{label(p)}}</option></select></div></div>
  </template>
  <template v-else-if="section==='projects'&&!selectedId">
   <header class="module-header"><div><div class="eyebrow">TURN INTENTION INTO PROGRESS</div><h1>Projects</h1><p>A home for the things you're building.</p></div><button class="btn btn-primary" @click="emit('edit','projects')"><Plus :size="17"/> New project</button></header>
   <div class="filters"><select v-model="statusFilter" aria-label="Filter projects by status"><option value="">All statuses</option><option v-for="s in ['active','planned','paused','completed','archived']" :key="s" :value="s">{{label(s)}}</option></select><select v-model="goalFilter" aria-label="Filter projects by goal"><option value="">All goals</option><option v-for="g in lookups.goals" :key="g.id" :value="g.id">{{g.title}}</option></select><select v-model="sort" aria-label="Sort projects"><option value="focus">Current focus first</option><option value="updated">Recently updated</option><option value="target_date">Target date</option><option value="name">Name</option></select><input v-model="query" placeholder="Find a project..." aria-label="Search projects"/></div>
   <div v-if="rows.length" class="record-grid project-grid"><article v-for="p in rows" :key="p.id" class="record-card project-card"><div class="project-card-top"><span class="project-symbol"><FolderKanban :size="23" stroke-width="1.5"/></span><span v-if="p.is_current_focus" class="badge focus-badge"><Star :size="11"/> Current focus</span><span v-else class="badge" :class="'status-'+p.status">{{label(p.status)}}</span></div><Link :href="`/projects/${p.id}`" class="project-card-title"><h2>{{p.name}}</h2></Link><p>{{p.description||'Give this project a little direction.'}}</p><div class="project-progress-label"><span>{{p.completed_count}} / {{p.task_count}} tasks</span><strong>{{p.progress}}%</strong></div><div class="progress-bar"><span :style="{width:p.progress+'%'}"></span></div><div class="project-card-meta"><span><CalendarDays :size="13"/>{{p.target_date?date(p.target_date):'No target date'}}</span><button class="btn-icon" :aria-label="'Edit '+p.name" @click="emit('edit','projects',p)"><Pencil :size="15"/></button></div><div class="record-actions"><Link :href="`/projects/${p.id}`" class="btn btn-secondary">Open project</Link><button v-if="p.status==='active'&&!p.is_current_focus" class="text-button" :disabled="busy.includes(p.id)" @click="action(`/data/projects/${p.id}/focus`,p.id)">Set focus</button></div></article></div>
   <div v-else-if="!loading" class="empty-state"><FolderKanban :size="36"/><h2>What would you like to build?</h2><p>Create a project and give your next steps a home.</p><button class="btn btn-primary" @click="emit('edit','projects')">Create project</button></div>
  </template>
  <template v-else-if="project">
   <Link href="/projects" class="back-link"><ChevronLeft :size="16"/> All projects</Link>
   <header class="module-header project-detail-header"><div><div class="project-detail-badges"><span class="badge" :class="'status-'+project.status">{{label(project.status)}}</span><span v-if="project.is_current_focus" class="badge focus-badge"><Star :size="11"/> Current focus</span></div><h1>{{project.name}}</h1><p>{{project.description}}</p></div><div class="record-actions"><button class="btn btn-secondary" @click="emit('edit','projects',project)"><Pencil :size="15"/> Edit project</button><button v-if="project.status==='active'&&!project.is_current_focus" class="btn btn-secondary" :disabled="busy.includes(project.id)" @click="action(`/data/projects/${project.id}/focus`,project.id)"><Target :size="15"/> Set focus</button><button class="btn-icon" aria-label="Delete project" @click="remove('projects',project)"><Trash2 :size="16"/></button></div></header>
   <div class="project-summary card"><div><span>Project progress</span><strong>{{project.progress}}%</strong><div class="progress-track"><span :style="{width:project.progress+'%'}"></span></div></div><div><span>Completed tasks</span><strong>{{project.completed_count}} <small>/ {{project.task_count}}</small></strong></div><div><span>Target date</span><strong class="summary-text">{{project.target_date?date(project.target_date):'No date set'}}</strong></div><div><span>Supports your goal</span><Link v-if="goal" :href="`/goals/${goal.id}`" class="summary-goal"><Target :size="15"/>{{goal.title}}</Link><strong v-else class="summary-text">No goal linked</strong></div></div>
   <p v-if="project.brief" class="project-brief">{{project.brief}}</p>
   <div class="module-toolbar"><div class="tabs"><button class="tab" :class="{active:projectView==='board'}" @click="projectView='board'"><LayoutGrid :size="14"/> Board</button><button class="tab" :class="{active:projectView==='list'}" @click="projectView='list'"><List :size="14"/> List</button><button class="tab" :class="{active:projectView==='notes'}" @click="projectView='notes'"><FileText :size="14"/> Notes</button></div><button class="btn btn-primary" @click="projectView==='notes'?emit('edit','notes',undefined,{notable_type:'project',notable_id:project.id}):emit('edit','tasks',undefined,{project_id:project.id})"><Plus :size="16"/>{{projectView==='notes'?'Add note':'Add task'}}</button></div>
   <div v-if="projectView==='board'" class="kanban-board"><section v-for="stage in stages" :key="stage" class="kanban-column" :class="{'drag-over':hoverColumn===stage}" @dragover.prevent="hoverColumn=stage" @dragleave.self="hoverColumn=''" @drop.prevent="drop($event,stage)"><header><span><span class="column-dot" :class="stage"></span>{{labels[stage]}}</span><span class="badge">{{stageTasks(stage).length}}</span></header><article v-for="task in stageTasks(stage)" :key="task.id" class="kanban-card" :draggable="!busy.includes('move')" @dragstart="startDrag($event,task)" @dragend="dragged='';hoverColumn=''" @dragover.prevent.stop @drop.prevent.stop="drop($event,stage,task.id)"><div class="kanban-task-top"><span class="badge" :class="'priority-'+task.priority">{{label(task.priority)}}</span><GripVertical :size="14"/></div><button class="kanban-task-title" @click="emit('edit','tasks',task)">{{task.title}}</button><p v-if="task.due_date||task.planned_date"><CalendarDays :size="12"/>{{date(task.due_date||task.planned_date)}}<span v-if="task.is_overdue" class="overdue-label">Overdue</span></p><select :value="task.status" :disabled="busy.includes('move')" :aria-label="'Status for '+task.title" @change="moveTask(task.id,($event.target as HTMLSelectElement).value)"><option v-for="s in stages" :key="s" :value="s">{{labels[s]}}</option></select></article><button class="text-button" @click="emit('edit','tasks',undefined,{project_id:project.id,status:stage})"><Plus :size="14"/>Add task</button></section></div>
   <template v-if="projectView==='notes'"><div v-if="data.notes?.length" class="record-grid"><article v-for="note in data.notes" :key="note.id" class="record-card"><h3>{{note.title||'Untitled note'}}</h3><p>{{note.body}}</p><button class="text-button" @click="emit('edit','notes',note)"><Pencil :size="14"/>Edit note</button></article></div><div v-else class="empty-state"><FileText :size="30"/><h3>Keep your thinking close.</h3><p>Add a brief, reference, or note to this project.</p></div></template>
  </template>

  <template v-if="section==='today'||(selectedId&&projectView==='list')">
   <div v-if="openTasks.length" class="task-list"><article v-for="task in openTasks" :key="task.id" class="task-row"><button class="task-checkbox" :disabled="busy.includes(task.id)" :aria-label="'Complete '+task.title" @click="action(`/data/tasks/${task.id}/complete`,task.id)"></button><div class="task-main"><button class="task-title" @click="emit('edit','tasks',task)">{{task.title}}</button><div class="task-meta"><span v-if="taskProject(task)">{{taskProject(task)}}</span><span v-if="task.due_date">Due {{date(task.due_date)}}</span><span v-if="task.is_overdue" class="overdue-label">Overdue</span></div></div><span class="badge" :class="'priority-'+task.priority">{{label(task.priority)}}</span><div class="record-actions"><button class="btn-icon" :aria-label="'Edit '+task.title" @click="emit('edit','tasks',task)"><Pencil :size="15"/></button><button class="btn-icon" :aria-label="'Delete '+task.title" @click="remove('tasks',task)"><Trash2 :size="15"/></button></div></article></div>
   <div v-if="completedTasks.length" class="completed-section"><button class="completed-toggle" @click="showCompleted=!showCompleted"><Check :size="17"/>Completed ({{completedTasks.length}})<ChevronRight :size="15" :class="{rotated:showCompleted}"/></button><div v-if="showCompleted" class="task-list"><article v-for="task in completedTasks" :key="task.id" class="task-row done"><button class="task-checkbox done" :disabled="busy.includes(task.id)" :aria-label="'Reopen '+task.title" @click="action(`/data/tasks/${task.id}/complete`,task.id)"><Check :size="13"/></button><div class="task-main"><button class="task-title" @click="emit('edit','tasks',task)">{{task.title}}</button><div class="task-meta"><span>{{taskProject(task)}}</span></div></div><button class="btn-icon" :aria-label="'Edit '+task.title" @click="emit('edit','tasks',task)"><Pencil :size="15"/></button></article></div></div>
   <div v-if="!rows.length&&!loading" class="empty-state"><ListTodo :size="35"/><h2>{{filter==='overdue'?'All caught up.':'A clear space for your next step.'}}</h2><p>{{filter==='overdue'?'No overdue tasks match these filters.':'Add a task or adjust your filters to see more.'}}</p><button class="btn btn-secondary" @click="emit('edit','tasks',undefined,selectedId?{project_id:selectedId}:{planned_date:today})">Add a task</button></div>
  </template>
  <p v-if="loading" class="loading-copy muted" role="status">Loading your {{entity}}...</p>
  <nav v-if="lastPage>1&&(projectView!=='notes'||!selectedId)" class="pagination" aria-label="List pagination"><button class="btn btn-secondary" :disabled="loading||page<=1" @click="load(page-1)"><ChevronLeft :size="15"/>Previous</button><span>Page {{page}} of {{lastPage}} · {{total}} {{entity}}</span><button class="btn btn-secondary" :disabled="loading||page>=lastPage" @click="load(page+1)">Next<ChevronRight :size="15"/></button></nav>
 </section>
</template>

<style scoped>
.module-header h1{margin-top:7px}.module-toolbar .tabs,.module-toolbar .filters{margin:0}.module-toolbar{margin:24px 0}.tab{display:inline-flex;align-items:center;gap:6px}.task-view-progress{display:flex;align-items:center;gap:13px;max-width:360px;margin-top:20px}.task-view-progress>.progress-track{flex:1}.task-view-progress>span{font-size:.75rem;color:#929baa}.project-card{padding:24px}.project-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.project-symbol{display:flex;padding:11px;background:#f0f3f7;border-radius:11px;color:#7491ac}.focus-badge{background:#f9eee5;color:#ae7b55}.project-card h2{margin-top:22px}.project-card>p{min-height:48px;font-size:.85rem;margin-bottom:23px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.project-progress-label{display:flex;justify-content:space-between;gap:10px;font-size:.75rem;color:#929ba9}.project-progress-label strong{color:#6f7987}.project-card>.progress-bar{margin:10px 0 18px}.project-card-meta{display:flex;justify-content:space-between;align-items:center;gap:10px}.project-card-meta>span{display:flex;align-items:center;gap:6px;font-size:.75rem;color:#8e98a5}.project-card .record-actions{padding-top:15px;border-top:1px solid var(--border);justify-content:space-between}.project-card-title:hover{color:var(--accent)}.back-link{display:flex;align-items:center;gap:5px;font-size:.8rem;color:#8d96a3;margin-bottom:25px}.project-detail-header .record-actions{margin:0}.project-detail-header h1{margin:12px 0 9px}.project-detail-badges{display:flex;gap:9px}.project-summary{display:grid;grid-template-columns:1fr .85fr .85fr 1.35fr;gap:25px;margin:25px 0}.project-summary>div>span{display:block;font-size:.7rem;color:#929ba7}.project-summary strong{display:block;font-size:1.6rem;margin:8px 0 11px;font-weight:600}.project-summary strong small{font-size:1rem;color:#a0a7b2}.project-summary .summary-text{font-size:.9rem;margin-top:15px;letter-spacing:0;font-weight:550}.summary-goal{display:flex;align-items:center;gap:7px;font-size:.85rem;margin-top:15px;color:#a46a53;line-height:1.5}.project-brief{white-space:pre-wrap;color:#7b8797;font-size:.9rem;margin:25px 5px;line-height:1.8}.column-dot{width:7px;height:7px;display:inline-block;background:#bac1ce;border-radius:3px;margin-right:8px}.column-dot.todo{background:#ccac77}.column-dot.in_progress{background:#8eacd1}.column-dot.done{background:#87ae9b}.kanban-task-top{display:flex;justify-content:space-between;align-items:center;color:#c0c4ce}.kanban-task-title{text-align:left;font-size:.875rem;line-height:1.6;font-weight:550;margin:12px 0 3px}.kanban-card>p{display:flex;align-items:center;gap:5px;font-size:.68rem}.priority-high{background:#fcf0e3;color:#b37f43}.priority-urgent{background:#fbeceb;color:#c4736a}.priority-low{background:#eef3f7;color:#8797aa}.overdue-label{color:#b86055;font-size:.7rem}.completed-section{margin-top:25px}.completed-toggle{display:flex;align-items:center;gap:8px;font-size:.83rem;color:#919ba8;margin-bottom:15px}.completed-toggle .rotated{transform:rotate(90deg)}.loading-copy{margin-top:20px;font-size:.8rem}
@media(max-width:900px){.project-summary{grid-template-columns:1fr 1fr;gap:20px}.module-toolbar .filters{width:100%;}.project-summary strong{font-size:1.5rem}.project-summary .summary-text{font-size:.85rem}}@media(max-width:767px){.module-header h1{font-size:1.7rem}.project-card{padding:21px}.project-detail-header .record-actions{flex-wrap:wrap}.project-summary{padding:19px;gap:20px}.project-summary>div>span{font-size:.65rem}.project-summary strong{font-size:1.3rem}.summary-goal{font-size:.75rem}.module-toolbar .tabs{width:100%;}.pagination{font-size:.65rem;gap:7px}.pagination .btn{padding:8px;font-size:.7rem}}
</style>
